command:
qm guest exec 310 --timeout 60 -- powershell.exe -NoProfile -NonInteractive -Command '
$ErrorActionPreference='\''Stop'\''
$adapters=@(Get-NetAdapter | Where-Object Status -eq '\''Up'\'')
if($adapters.Count -ne 1){throw '\''Expected one active test adapter'\''}
$before=Get-CimInstance Win32_ComputerSystem
if(-not $before.PartOfDomain -or -not (Test-ComputerSecureChannel)){throw '\''Initial trust check failed'\''}
$offline=$null
try {
    $adapters | Disable-NetAdapter -Confirm:$false
    Start-Sleep -Seconds 3
    $c=Get-CimInstance Win32_ComputerSystem
    $w=Get-ItemProperty '\''HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Winlogon'\''
    $offline=[pscustomobject]@{ActiveAdapters=@(Get-NetAdapter | Where-Object Status -eq '\''Up'\'').Count;PartOfDomain=$c.PartOfDomain;Domain=$c.Domain;CachedLogonsCount=$w.CachedLogonsCount;ForceUnlockLogon=$w.ForceUnlockLogon}
} finally {
    $adapters | Enable-NetAdapter -Confirm:$false
}
$healthy=$false
for($i=0;$i -lt 15;$i++){
    Start-Sleep -Seconds 2
    try {if(Test-ComputerSecureChannel -ErrorAction Stop){$healthy=$true;break}} catch {}
}
$pass=$offline.ActiveAdapters -eq 0 -and $offline.PartOfDomain -and $offline.Domain -eq $before.Domain -and $offline.CachedLogonsCount -eq '\''0'\'' -and $offline.ForceUnlockLogon -eq 1 -and $healthy
[pscustomobject]@{ReadAt=(Get-Date).ToString('\''o'\'');Computer=$env:COMPUTERNAME;Offline=$offline;RestoredSecureChannel=$healthy;RestoredActiveAdapters=@(Get-NetAdapter | Where-Object Status -eq '\''Up'\'').Count;Pass=$pass} | ConvertTo-Json -Depth 4 -Compress
if(-not $pass){exit 1}
'
